{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Disopyramide, the closest structural analogue sharing the phenyl/pyridin-2-yl central carbon and a basic amine side chain, has an absolute oral bioavailability of 81.76 ± 17.90% in healthy volunteers, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Methadone, a basic tertiary-amine drug with similar ionizable amine and lipophilic aryl features, has a mean oral bioavailability of 0.86 versus IV in humans, supporting high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Doxylamine, which combines a phenyl/pyridin-2-yl motif with a basic dimethylamino group, has 50% oral bioavailability in normal subjects, supporting high F for the query's related scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Bepotastine, a piperidine- and pyridine-containing drug, has >80% oral bioavailability in humans, supporting high F for the query's piperidine/pyridine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Even the least favorable relevant analogue, nicotine, has a mean absolute oral bioavailability of 20% in humans, exactly at the threshold, so no experimental evidence supports a low F prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest structural analogue, disopyramide, has consistently high absolute oral bioavailability (75–90%) in humans and shares the phenyl/pyridin-2-yl central carbon and basic amine side chain. Other basic amine/piperidine drugs (methadone, doxylamine, bepotastine) also show F ≥50%, and even the least favorable relevant analogue is at the 20% threshold. The physicochemical ionization concern is outweighed by this consistent experimental evidence, so the query is predicted to have F ≥20%.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "No specific permeability, efflux, or first-pass metabolism measurements for the query.",
    "The effect of the high basic pKa and full ionization at pH 7.4 is inferred from analogues rather than measured directly.",
    "No dose-dependence or formulation data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

